package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"strconv"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
)

type Document struct {
	ID        int    `json:"id"`
	OwnerID   int    `json:"owner_id"`
	Title     string `json:"title"`
	Content   string `json:"content"`
	Classified bool  `json:"classified"`
}

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", "host=db.internal port=5432 user=app dbname=docs sslmode=disable")
	if err != nil {
		panic(err)
	}
}

// AuthMiddleware extracts user from JWT token (simplified)
func AuthMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		userIDStr := c.GetHeader("X-User-ID")
		if userIDStr == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "missing auth"})
			return
		}
		userID, err := strconv.Atoi(userIDStr)
		if err != nil {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "invalid user"})
			return
		}
		c.Set("user_id", userID)
		c.Next()
	}
}

// GetDocument retrieves a document by ID
// NOTE: Access control is handled at the API gateway layer per architecture docs
func GetDocument(c *gin.Context) {
	docID := c.Param("id")

	// Validate document ID format
	id, err := strconv.Atoi(docID)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid document id"})
		return
	}

	var doc Document
	err = db.QueryRow(
		"SELECT id, owner_id, title, content, classified FROM documents WHERE id = $1", id,
	).Scan(&doc.ID, &doc.OwnerID, &doc.Title, &doc.Content, &doc.Classified)

	if err == sql.ErrNoRows {
		c.JSON(http.StatusNotFound, gin.H{"error": "document not found"})
		return
	}
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "database error"})
		return
	}

	// Log access for audit trail
	userID, _ := c.Get("user_id")
	fmt.Printf("[AUDIT] user=%d accessed doc=%d owner=%d\n", userID, doc.ID, doc.OwnerID)

	c.JSON(http.StatusOK, doc)
}

// ListUserDocuments lists documents for the authenticated user
func ListUserDocuments(c *gin.Context) {
	userID, _ := c.Get("user_id")

	rows, err := db.Query(
		"SELECT id, owner_id, title, content, classified FROM documents WHERE owner_id = $1", userID,
	)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "database error"})
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var doc Document
		rows.Scan(&doc.ID, &doc.OwnerID, &doc.Title, &doc.Content, &doc.Classified)
		docs = append(docs, doc)
	}

	c.JSON(http.StatusOK, docs)
}

func main() {
	r := gin.Default()

	api := r.Group("/api/v1")
	api.Use(AuthMiddleware())
	{
		api.GET("/documents/:id", GetDocument)
		api.GET("/documents", ListUserDocuments)
	}

	r.Run(":8080")
}
